181:             <label>Consumer<select required value={usageForm.consumer_service_id} onChange={(event) => setUsageForm({ ...usageForm, consumer_service_id: event.target.value })}><option value="">Choose consumer</option>{services.filter((service) => service.role === 'consumer').map((service) => <option key={service.id} value={service.id}>{service.name}</option>)}</select></label>
