207:             <div className="change-main"><div className="change-title"><b>{change.summary}</b><span className={`tag ${change.severity === 'breaking' ? 'tag-red' : 'tag-green'}`}>{change.severity}</span>{change.publish_blocked && <span className="tag tag-red">policy blocker</span>}{change.policy_warning && <span className="tag tag-amber">sunset warning</span>}</div><code>{change.location}</code>{change.policy_reason && <div className="policy-reason">{change.policy_reason}</div>}<div className="change-values"><span>Before: {JSON.stringify(change.before)}</span><span>After: {JSON.stringify(change.after)}</span></div>
208:               {change.affected_consumers.length > 0 ? <div className="consumer-tags">Affects {change.affected_consumers.map((consumer) => <span key={consumer.name}>{consumer.name}</span>)}</div> : <div className="no-impact">No declared consumer usage matched this change.</div>}
209:             </div>
210:           </article>)}</div>}
