223: function Metric({ label, value, detail, icon, tone = 'green' }) {
224:   return <div className="metric-card"><div className={`metric-icon ${tone}`}>{icon}</div><div><span className="metric-label">{label}</span><strong>{value}</strong><small>{detail}</small></div></div>;
225: }
226: 
227: export default App;

