 @media(max-width:1100px){.main-content{padding:28px 24px}.sidebar{width:210px}.main-content{margin-left:210px;width:calc(100% - 210px)}.metrics-grid{grid-template-columns:repeat(2,1fr)}.service-grid{grid-template-columns:1fr}.controls-row{flex-wrap:wrap}.controls-row label{flex:1 1 35%}.compare-button{flex:1}.history-row{grid-template-columns:80px 1fr 1.5fr}.history-row time{display:none}}@media(max-width:700px){.sidebar{width:58px;padding:18px 8px}.brand{padding:0 2px 25px}.brand>div:last-child,.nav-label,.nav-item:not(.active),.sidebar-bottom{display:none}.nav-item.active{font-size:0;justify-content:center}.nav-item.active span{font-size:18px}.main-content{margin-left:58px;width:calc(100% - 58px);padding:20px 13px}.topbar h1{font-size:20px}.welcome-row{align-items:flex-start;gap:14px;flex-direction:column}.metrics-grid{gap:8px}.metric-card{padding:11px;gap:8px;min-height:85px}.metric-card strong{font-size:19px}.panel{padding:15px 12px}.controls-row label{flex-basis:100%}.arrow{display:none}.upload-row{flex-wrap:wrap}.history-row{grid-template-columns:75px 1fr}.history-reason{display:none}}

